                ParallaxHover('.program','.program .dotted-1');
                function ParallaxHover($parent,$icon)
                {
                    var timeout;
                    $($parent).mousemove(function(e){
                    if(timeout) clearTimeout(timeout);
                    setTimeout(callParallax.bind(null, e), 100);
                    
                    });

                    function callParallax(e){
                        parallaxIt(e, $icon, 20);
                    }

                    function parallaxIt(e, target, movement){
                    var $this = $($parent);
                    var relX = e.pageX - $this.offset().left;
                    var relY = e.pageY - $this.offset().top;
                    
                    gsap.to(target, 1, {
                        x: (relX - $this.width()/2) / $this.width() * movement,
                        y: (relY - $this.height()/2) / $this.height() * movement,scale: 1,
                        ease: Power2.easeOut
                    })
                    }
                }

                if($('.program').length )
                {
                    var programSection = new gsap.timeline({paused:true});
                    ScrollTrigger.create({
                        trigger: '.program',
                        start: 'top 75%',
                        onEnter: programSectionAni,
                    // markers: true
                    });
                    function programSectionAni()
                    {
                        programSection.play();
                        
                    }
                    programSection.add(
                            gsap.fromTo('.program-content-wrap', 
                            {   alpha:0,
                                y:50,
                            }, {
                                duration:.75, 
                                alpha:1,
                               y:0,
                                ease: 'power4.easeOut',
                    }),"0"); 
                            
                   
                }

                if($('.gallery').length )
                {
                    var gallerySection = new gsap.timeline({paused:true});
                    ScrollTrigger.create({
                        trigger: '.gallery',
                        start: 'top 75%',
                        onEnter: gallerySectionAni,
                    // markers: true
                    });
                    function gallerySectionAni()
                    {
                        gallerySection.play();
                        
                    }
                    const gallerys = gsap.utils.toArray('.gallery-item');
                    gallerys.forEach((icon, i) => {
                        gallerySection.add(
                            gsap.fromTo(icon, 
                            {   alpha:0,
                                y:50,
                            }, {
                                duration:.75, 
                                alpha:1,
                               y:0,
                                ease: 'power4.easeOut',
                            }),
                            
                        "-=.35"); 
                    });
                
                }
            });
