    <script>
     jQuery(document).ready(function($){
            
            TreesAni();
            function TreesAni() 
            {
                var las = new gsap.timeline();
                var la1 = gsap.to('#la1,#la2,#la3,#la4,#la5,#la6,#la7,#la8,#cay1,#cay2,#cay3', 3, {
                    delay: 0.5,
                    repeat: -1,
                    transformOrigin: '0% 100%',
                    skewX: -15,
                    yoyo: true,
                    ease: Sine.easeInOut
                })
                
                las.add(la1, 0);
            }

            function Random(min,max) {return min+Math.random()*(max-min)};

            EyeANi();
            function EyeANi(){
               
                gsap.to('#mat1,#mat2,#mat3', Random(0.3,0.5), {
                    scaleY: 0.2,
                    yoyo: true,
                    repeat: 1,
                    transformOrigin: '50% 50%',
                    delay: Math.random() * 5,
                    onComplete:EyeANi
                    });
            }

            PinWheel();
            function PinWheel()
            {
                gsap.to('#banh1', 5, {
                rotation:"+=360",
                yoyo: false,
                ease: Power0.easeNone,
                transformOrigin: "0% 100%",
                repeat: -1,
                })

                gsap.to('#banh2', 5, {
                rotation:"+=360",
                yoyo: false,
                ease: Power0.easeNone,
                transformOrigin: "0% 0%",
                repeat: -1,
                })
            }

            Flag();
            function Flag()
            {
                
                var flag1 = gsap.to('#laco', 1.2, {
                    repeatDelay: 0,
                    repeat: -1,
                    rotation: -7, 
                    skewY: -6,
                    transformOrigin:"100% 0%",
                    yoyo: true,
                    ease: Sine.easeInOut
                })
                
                var flag = new gsap.timeline({repeat:-1});
                flag.add(flag1);
            }
    });
    </script>
